// Skyline Office, a level for examples/tremor.psh
//
// A two-storey office floor near the top of a tower, looking out over a night
// city through a curtain wall that leans outwards as it rises. The lower floor
// is an open atrium with a glass-fronted office on either side; a mezzanine
// runs around the back and both sides at 4.8, reached by a flight of stairs,
// and looks down into it and out of the window.
//
// The window plane is the one thing here worth stating in numbers, because
// every piece of the curtain wall sits on it:
//
//     z = 0.4 * (y - 1.6)
//
// so it meets the floor slab at z = -0.64, crosses z = 0 at the sill line
// y = 1.6, and reaches the ceiling at y = 9.6, z = 3.2. The spandrel under the
// sill, the transom that splits the window and the mullions that divide it are
// all `slab` brushes whose front face runs along that line: give a slab the two
// ends of that face and it stands its own thickness behind them, so a mullion
// is a narrow one and leans exactly as much as the wall it sits in.
//
// The glass fills the bays left between them, on a plane 0.16 further out so
// that the frame stands proud of it. The shell reaches z 3.6 rather than 3.2 so
// that the ceiling and the two piers close over that further out plane instead
// of leaving a slot of sky open along the head of every bay.
//
// Nothing is lit by hand except the fixtures and the city outside. The city is
// held at fixed levels: its windows are lit in the texture itself and no lamp
// in here reaches it, and a fixed level costs no ray casts at load time. The
// levels step down with distance, which is what puts air between the towers.
//
// Usage: plush examples/tremor.psh examples/data/office.map

spawn x=0 y=1.6 z=-14 yaw=0

// ===========================================================================
// Shell: interior x -14.4..14.4, z -19.2..the window, floor 0, ceiling 9.6
// ===========================================================================

// The floor, and the tower it stands on. The tower's z face is our own facade
// falling away below the window, which is what you see looking steeply down.
box   x0=-16 y0=-0.8 z0=-20.8 x1=16 y1=0 z1=0 tex=concrete_white top=carpet_blue scale=100
box   x0=-16 y0=-56 z0=-20.8 x1=16 y1=-0.8 z1=0 tex=skyscraper_03 scale=10 light=8

// The side offices project from the tower as shallow glazed wings. Their
// carpet stops at the inside face of both exterior window walls.
box   x0=-26.4 y0=-0.8 z0=-15.2 x1=-14.8 y1=0 z1=0.16 tex=concrete_white top=carpet_blue scale=100
box   x0=14.8 y0=-0.8 z0=-15.2 x1=26.4 y1=0 z1=0.16 tex=concrete_white top=carpet_blue scale=100
box   x0=-27.2 y0=-30 z0=-15.2 x1=-16 y1=-0.8 z1=0.16 tex=skyscraper_03 scale=10 light=8
box   x0=16 y0=-30 z0=-15.2 x1=27.2 y1=-0.8 z1=0.16 tex=skyscraper_03 scale=10 light=8

// The ceiling slab reaches out to z 3.2, where the window plane meets it, and
// the storeys above carry the facade on up past the head of the glass
box   x0=-16 y0=9.6 z0=-20.8 x1=16 y1=10.4 z1=3.6 tex=concrete_white bottom=ceiling_tile scale=160
box   x0=-16 y0=10.4 z0=-20.8 x1=16 y1=64 z1=3.6 tex=skyscraper_03 scale=10 light=8

// A low ceiling makes each side office feel enclosed beneath the mezzanine.
box   x0=-26.4 y0=4.8 z0=-15.2 x1=-14.8 y1=5.6 z1=0.16 tex=concrete_white bottom=ceiling_tile scale=160
box   x0=14.8 y0=4.8 z0=-15.2 x1=26.4 y1=5.6 z1=0.16 tex=concrete_white bottom=ceiling_tile scale=160

// Back wall, and the upper halves of the two side walls. The lower halves are
// opened into the adjacent offices below; above them the walls still read as
// piers standing either side of the main curtain wall.
box   x0=-16 y0=0 z0=-20.8 x1=16 y1=9.6 z1=-19.2 tex=beigewall
box   x0=-16 y0=4.8 z0=-20.8 x1=-14.4 y1=9.6 z1=3.6 tex=beigewall
box   x0=14.4 y0=4.8 z0=-20.8 x1=16 y1=9.6 z1=3.6 tex=beigewall

// Lower side walls frame a doorway and two interior windows on each side.
box   x0=-14.8 y0=0 z0=-20.8 x1=-14.4 y1=4.8 z1=-11.8 tex=beigewall
box   x0=-14.8 y0=3.2 z0=-11.8 x1=-14.4 y1=4.8 z1=-9 tex=beigewall
box   x0=-14.8 y0=0 z0=-9 x1=-14.4 y1=1 z1=-1.2 tex=beigewall
box   x0=-14.8 y0=4 z0=-9 x1=-14.4 y1=4.8 z1=-1.2 tex=beigewall
box   x0=-14.8 y0=1 z0=-9 x1=-14.4 y1=4 z1=-8.6 tex=metal_plate scale=50
box   x0=-14.8 y0=1 z0=-5.3 x1=-14.4 y1=4 z1=-4.9 tex=metal_plate scale=50
box   x0=-14.8 y0=1 z0=-1.6 x1=-14.4 y1=4 z1=-1.2 tex=metal_plate scale=50
box   x0=-14.8 y0=-56 z0=-1.2 x1=-14.4 y1=4.8 z1=3.6 tex=beigewall

box   x0=14.4 y0=0 z0=-20.8 x1=14.8 y1=4.8 z1=-11.8 tex=beigewall
box   x0=14.4 y0=3.2 z0=-11.8 x1=14.8 y1=4.8 z1=-9 tex=beigewall
box   x0=14.4 y0=0 z0=-9 x1=14.8 y1=1 z1=-1.2 tex=beigewall
box   x0=14.4 y0=4 z0=-9 x1=14.8 y1=4.8 z1=-1.2 tex=beigewall
box   x0=14.4 y0=1 z0=-9 x1=14.8 y1=4 z1=-8.6 tex=metal_plate scale=50
box   x0=14.4 y0=1 z0=-5.3 x1=14.8 y1=4 z1=-4.9 tex=metal_plate scale=50
box   x0=14.4 y0=1 z0=-1.6 x1=14.8 y1=4 z1=-1.2 tex=metal_plate scale=50
box   x0=14.4 y0=-56 z0=-1.2 x1=14.8 y1=4.8 z1=3.6 tex=beigewall

// Thin panes sit midway through the slim partition reveals.
box   x0=-14.64 y0=1 z0=-8.6 x1=-14.56 y1=4 z1=-5.3 nx=glass_grey px=glass_grey light=9 alpha=0.15 fit
box   x0=-14.64 y0=1 z0=-4.9 x1=-14.56 y1=4 z1=-1.6 nx=glass_grey px=glass_grey light=9 alpha=0.15 fit
box   x0=14.56 y0=1 z0=-8.6 x1=14.64 y1=4 z1=-5.3 nx=glass_grey px=glass_grey light=9 alpha=0.15 fit
box   x0=14.56 y0=1 z0=-4.9 x1=14.64 y1=4 z1=-1.6 nx=glass_grey px=glass_grey light=9 alpha=0.15 fit

// ===========================================================================
// The curtain wall. Every slab below has its front face on the window plane,
// and what is left open between them are the bays of glass.
// ===========================================================================

// The spandrel from the floor up to the sill, and the transom at 5.6 that
// splits the window into a lower and an upper light
slab  x0=-14.4 y0=0 z0=-0.64 x1=14.4 y1=1.6 z1=0 thick=0.5 tex=concrete_01 scale=50
slab  x0=-14.4 y0=5.6 z0=1.6 x1=14.4 y1=6 z1=1.76 thick=0.5 tex=concrete_white scale=50

// Six mullions, each in two runs so that they meet the transom rather than
// pass through it: sill to transom first, then transom to ceiling
slab  x0=-11.8 y0=1.6 z0=0 x1=-11.4 y1=5.6 z1=1.6 thick=0.5 tex=metal_plate scale=50
slab  x0=-7.4 y0=1.6 z0=0 x1=-7 y1=5.6 z1=1.6 thick=0.5 tex=metal_plate scale=50
slab  x0=-2.6 y0=1.6 z0=0 x1=-2.2 y1=5.6 z1=1.6 thick=0.5 tex=metal_plate scale=50
slab  x0=2.2 y0=1.6 z0=0 x1=2.6 y1=5.6 z1=1.6 thick=0.5 tex=metal_plate scale=50
slab  x0=7 y0=1.6 z0=0 x1=7.4 y1=5.6 z1=1.6 thick=0.5 tex=metal_plate scale=50
slab  x0=11.4 y0=1.6 z0=0 x1=11.8 y1=5.6 z1=1.6 thick=0.5 tex=metal_plate scale=50

slab  x0=-11.8 y0=6 z0=1.76 x1=-11.4 y1=9.6 z1=3.2 thick=0.5 tex=metal_plate scale=50
slab  x0=-7.4 y0=6 z0=1.76 x1=-7 y1=9.6 z1=3.2 thick=0.5 tex=metal_plate scale=50
slab  x0=-2.6 y0=6 z0=1.76 x1=-2.2 y1=9.6 z1=3.2 thick=0.5 tex=metal_plate scale=50
slab  x0=2.2 y0=6 z0=1.76 x1=2.6 y1=9.6 z1=3.2 thick=0.5 tex=metal_plate scale=50
slab  x0=7 y0=6 z0=1.76 x1=7.4 y1=9.6 z1=3.2 thick=0.5 tex=metal_plate scale=50
slab  x0=11.4 y0=6 z0=1.76 x1=11.8 y1=9.6 z1=3.2 thick=0.5 tex=metal_plate scale=50

// The glass. One pane per bay, on a plane 0.16 further out than the frame, so
// that the mullions and the transom stand proud of it. Panes are 6 cm thick
// and take a flat light level rather than a baked one: a sheet of glass has no
// shading of its own to speak of, and a level that holds still across the face
// is also the cheapest thing to blend, since it collapses to one multiplier for
// the whole pane instead of a step per pixel.
//
// alpha keeps three tenths of the pane and lets seven through, so the city
// reads as the city with a tint over it rather than through a curtain. The
// level and the alpha are separate: the level is how bright the glass itself
// is, the alpha is how much of the city survives it.
slab  x0=-14.4 y0=1.6 z0=0.16 x1=-11.8 y1=5.6 z1=1.76 thick=0.06 tex=glass_grey light=9 alpha=0.15 fit
slab  x0=-11.4 y0=1.6 z0=0.16 x1=-7.4 y1=5.6 z1=1.76 thick=0.06 tex=glass_grey light=9 alpha=0.15 fit
slab  x0=-7 y0=1.6 z0=0.16 x1=-2.6 y1=5.6 z1=1.76 thick=0.06 tex=glass_grey light=9 alpha=0.15 fit
slab  x0=-2.2 y0=1.6 z0=0.16 x1=2.2 y1=5.6 z1=1.76 thick=0.06 tex=glass_grey light=9 alpha=0.15 fit
slab  x0=2.6 y0=1.6 z0=0.16 x1=7 y1=5.6 z1=1.76 thick=0.06 tex=glass_grey light=9 alpha=0.15 fit
slab  x0=7.4 y0=1.6 z0=0.16 x1=11.4 y1=5.6 z1=1.76 thick=0.06 tex=glass_grey light=9 alpha=0.15 fit
slab  x0=11.8 y0=1.6 z0=0.16 x1=14.4 y1=5.6 z1=1.76 thick=0.06 tex=glass_grey light=9 alpha=0.15 fit

slab  x0=-14.4 y0=6 z0=1.92 x1=-11.8 y1=9.6 z1=3.36 thick=0.06 tex=glass_grey light=9 alpha=0.15 fit
slab  x0=-11.4 y0=6 z0=1.92 x1=-7.4 y1=9.6 z1=3.36 thick=0.06 tex=glass_grey light=9 alpha=0.15 fit
slab  x0=-7 y0=6 z0=1.92 x1=-2.6 y1=9.6 z1=3.36 thick=0.06 tex=glass_grey light=9 alpha=0.15 fit
slab  x0=-2.2 y0=6 z0=1.92 x1=2.2 y1=9.6 z1=3.36 thick=0.06 tex=glass_grey light=9 alpha=0.15 fit
slab  x0=2.6 y0=6 z0=1.92 x1=7 y1=9.6 z1=3.36 thick=0.06 tex=glass_grey light=9 alpha=0.15 fit
slab  x0=7.4 y0=6 z0=1.92 x1=11.4 y1=9.6 z1=3.36 thick=0.06 tex=glass_grey light=9 alpha=0.15 fit
slab  x0=11.8 y0=6 z0=1.92 x1=14.4 y1=9.6 z1=3.36 thick=0.06 tex=glass_grey light=9 alpha=0.15 fit

// ===========================================================================
// The mezzanine: a gallery along the back and both sides at 4.8, with a
// soffit over it at 8.8 that leaves the middle of the room full height
// ===========================================================================

box   x0=-14.4 y0=4.4 z0=-19.2 x1=14.4 y1=4.8 z1=-14.4 tex=wood top=carpet_blue bottom=ceiling_tile scale=100
box   x0=-14.4 y0=4.4 z0=-14.4 x1=-9.6 y1=4.8 z1=0 tex=wood top=carpet_blue bottom=ceiling_tile scale=100
box   x0=9.6 y0=4.4 z0=-14.4 x1=14.4 y1=4.8 z1=0 tex=wood top=carpet_blue bottom=ceiling_tile scale=100

// The stairs up to it, off to one side so the middle of the room stays clear.
// Sixteen steps of 0.3 by 0.5, landing on the gallery edge at z -14.4.
box   x0=-8.8 y0=0 z0=-6.9 x1=-4 y1=0.3 z1=-6.4 tex=concrete_white top=marble_white scale=90
box   x0=-8.8 y0=0 z0=-7.4 x1=-4 y1=0.6 z1=-6.9 tex=concrete_white top=marble_white scale=90
box   x0=-8.8 y0=0 z0=-7.9 x1=-4 y1=0.9 z1=-7.4 tex=concrete_white top=marble_white scale=90
box   x0=-8.8 y0=0 z0=-8.4 x1=-4 y1=1.2 z1=-7.9 tex=concrete_white top=marble_white scale=90
box   x0=-8.8 y0=0 z0=-8.9 x1=-4 y1=1.5 z1=-8.4 tex=concrete_white top=marble_white scale=90
box   x0=-8.8 y0=0 z0=-9.4 x1=-4 y1=1.8 z1=-8.9 tex=concrete_white top=marble_white scale=90
box   x0=-8.8 y0=0 z0=-9.9 x1=-4 y1=2.1 z1=-9.4 tex=concrete_white top=marble_white scale=90
box   x0=-8.8 y0=0 z0=-10.4 x1=-4 y1=2.4 z1=-9.9 tex=concrete_white top=marble_white scale=90
box   x0=-8.8 y0=0 z0=-10.9 x1=-4 y1=2.7 z1=-10.4 tex=concrete_white top=marble_white scale=90
box   x0=-8.8 y0=0 z0=-11.4 x1=-4 y1=3 z1=-10.9 tex=concrete_white top=marble_white scale=90
box   x0=-8.8 y0=0 z0=-11.9 x1=-4 y1=3.3 z1=-11.4 tex=concrete_white top=marble_white scale=90
box   x0=-8.8 y0=0 z0=-12.4 x1=-4 y1=3.6 z1=-11.9 tex=concrete_white top=marble_white scale=90
box   x0=-8.8 y0=0 z0=-12.9 x1=-4 y1=3.9 z1=-12.4 tex=concrete_white top=marble_white scale=90
box   x0=-8.8 y0=0 z0=-13.4 x1=-4 y1=4.2 z1=-12.9 tex=concrete_white top=marble_white scale=90
box   x0=-8.8 y0=0 z0=-13.9 x1=-4 y1=4.5 z1=-13.4 tex=concrete_white top=marble_white scale=90
box   x0=-8.8 y0=0 z0=-14.4 x1=-4 y1=4.8 z1=-13.9 tex=concrete_white top=marble_white scale=90

// Parapets. The back one is in two pieces, with the gap where the stairs land.
box   x0=-9.76 y0=4.8 z0=-14.56 x1=-8.8 y1=5.8 z1=-14.4 tex=metal_01 top=wood
box   x0=-4 y0=4.8 z0=-14.56 x1=9.76 y1=5.8 z1=-14.4 tex=metal_01 top=wood
box   x0=-9.76 y0=4.8 z0=-14.4 x1=-9.6 y1=5.8 z1=0 tex=metal_01 top=wood
box   x0=9.6 y0=4.8 z0=-14.4 x1=9.76 y1=5.8 z1=0 tex=metal_01 top=wood
box   x0=-14.4 y0=4.8 z0=-0.16 x1=-9.76 y1=5.8 z1=0 tex=metal_01 top=wood
box   x0=9.76 y0=4.8 z0=-0.16 x1=14.4 y1=5.8 z1=0 tex=metal_01 top=wood

// The soffit over the gallery
box   x0=-14.4 y0=8.8 z0=-19.2 x1=14.4 y1=9.6 z1=-14.4 tex=concrete_white bottom=ceiling_tile scale=160
box   x0=-14.4 y0=8.8 z0=-14.4 x1=-9.6 y1=9.6 z1=0 tex=concrete_white bottom=ceiling_tile scale=160
box   x0=9.6 y0=8.8 z0=-14.4 x1=14.4 y1=9.6 z1=0 tex=concrete_white bottom=ceiling_tile scale=160

// ===========================================================================
// Side offices: low glass-fronted rooms flanking the main atrium
// ===========================================================================

// Back walls close the two wings behind their exterior windows.
box   x0=-27.2 y0=0 z0=-15.2 x1=-14.8 y1=4.8 z1=-14.4 tex=beigewall
box   x0=14.8 y0=0 z0=-15.2 x1=27.2 y1=4.8 z1=-14.4 tex=beigewall

// Full-height posts and mullions form three exterior window bays per office.
box   x0=-27.2 y0=0 z0=-14.4 x1=-26.4 y1=4.8 z1=-13 tex=concrete_white
box   x0=-27.2 y0=0 z0=-9.2 x1=-26.4 y1=4.8 z1=-8.8 tex=metal_plate scale=50
box   x0=-27.2 y0=0 z0=-5.2 x1=-26.4 y1=4.8 z1=-4.8 tex=metal_plate scale=50
box   x0=-27.2 y0=0 z0=-1 x1=-26.4 y1=4.8 z1=0 tex=concrete_white

box   x0=26.4 y0=0 z0=-14.4 x1=27.2 y1=4.8 z1=-13 tex=concrete_white
box   x0=26.4 y0=0 z0=-9.2 x1=27.2 y1=4.8 z1=-8.8 tex=metal_plate scale=50
box   x0=26.4 y0=0 z0=-5.2 x1=27.2 y1=4.8 z1=-4.8 tex=metal_plate scale=50
box   x0=26.4 y0=0 z0=-1 x1=27.2 y1=4.8 z1=0 tex=concrete_white

// The glass is inset behind the frame so the mullions stand proud like the
// main curtain wall.
box   x0=-26.48 y0=0.2 z0=-13 x1=-26.4 y1=4.6 z1=-9.2 nx=glass_grey px=glass_grey light=9 alpha=0.15 fit
box   x0=-26.48 y0=0.2 z0=-8.8 x1=-26.4 y1=4.6 z1=-5.2 nx=glass_grey px=glass_grey light=9 alpha=0.15 fit
box   x0=-26.48 y0=0.2 z0=-4.8 x1=-26.4 y1=4.6 z1=-1 nx=glass_grey px=glass_grey light=9 alpha=0.15 fit
box   x0=26.4 y0=0.2 z0=-13 x1=26.48 y1=4.6 z1=-9.2 nx=glass_grey px=glass_grey light=9 alpha=0.15 fit
box   x0=26.4 y0=0.2 z0=-8.8 x1=26.48 y1=4.6 z1=-5.2 nx=glass_grey px=glass_grey light=9 alpha=0.15 fit
box   x0=26.4 y0=0.2 z0=-4.8 x1=26.48 y1=4.6 z1=-1 nx=glass_grey px=glass_grey light=9 alpha=0.15 fit

// Twenty-centimetre wall-textured bands trim the top and bottom of each pane.
box   x0=-27.2 y0=0 z0=-13 x1=-26.4 y1=0.2 z1=-9.2 tex=beigewall
box   x0=-27.2 y0=4.6 z0=-13 x1=-26.4 y1=4.8 z1=-9.2 tex=beigewall
box   x0=-27.2 y0=0 z0=-8.8 x1=-26.4 y1=0.2 z1=-5.2 tex=beigewall
box   x0=-27.2 y0=4.6 z0=-8.8 x1=-26.4 y1=4.8 z1=-5.2 tex=beigewall
box   x0=-27.2 y0=0 z0=-4.8 x1=-26.4 y1=0.2 z1=-1 tex=beigewall
box   x0=-27.2 y0=4.6 z0=-4.8 x1=-26.4 y1=4.8 z1=-1 tex=beigewall

box   x0=26.4 y0=0 z0=-13 x1=27.2 y1=0.2 z1=-9.2 tex=beigewall
box   x0=26.4 y0=4.6 z0=-13 x1=27.2 y1=4.8 z1=-9.2 tex=beigewall
box   x0=26.4 y0=0 z0=-8.8 x1=27.2 y1=0.2 z1=-5.2 tex=beigewall
box   x0=26.4 y0=4.6 z0=-8.8 x1=27.2 y1=4.8 z1=-5.2 tex=beigewall
box   x0=26.4 y0=0 z0=-4.8 x1=27.2 y1=0.2 z1=-1 tex=beigewall
box   x0=26.4 y0=4.6 z0=-4.8 x1=27.2 y1=4.8 z1=-1 tex=beigewall

// Vertical front panes make the second outdoor side floor-to-ceiling as well.
// Their separating mullions use the same metal plate as the atrium beams.
slab  x0=-21.2 y0=0 z0=0 x1=-20.8 y1=4.8 z1=0 thick=0.5 tex=metal_plate scale=50
slab  x0=-26.4 y0=0.2 z0=0.16 x1=-21.2 y1=4.6 z1=0.16 thick=0.06 tex=glass_grey light=9 alpha=0.15 fit
slab  x0=-20.8 y0=0.2 z0=0.16 x1=-14.8 y1=4.6 z1=0.16 thick=0.06 tex=glass_grey light=9 alpha=0.15 fit
slab  x0=-26.4 y0=0 z0=0 x1=-21.2 y1=0.2 z1=0 thick=0.5 tex=beigewall
slab  x0=-26.4 y0=4.6 z0=0 x1=-21.2 y1=4.8 z1=0 thick=0.5 tex=beigewall
slab  x0=-20.8 y0=0 z0=0 x1=-14.8 y1=0.2 z1=0 thick=0.5 tex=beigewall
slab  x0=-20.8 y0=4.6 z0=0 x1=-14.8 y1=4.8 z1=0 thick=0.5 tex=beigewall

slab  x0=20.8 y0=0 z0=0 x1=21.2 y1=4.8 z1=0 thick=0.5 tex=metal_plate scale=50
slab  x0=14.8 y0=0.2 z0=0.16 x1=20.8 y1=4.6 z1=0.16 thick=0.06 tex=glass_grey light=9 alpha=0.15 fit
slab  x0=21.2 y0=0.2 z0=0.16 x1=26.4 y1=4.6 z1=0.16 thick=0.06 tex=glass_grey light=9 alpha=0.15 fit
slab  x0=14.8 y0=0 z0=0 x1=20.8 y1=0.2 z1=0 thick=0.5 tex=beigewall
slab  x0=14.8 y0=4.6 z0=0 x1=20.8 y1=4.8 z1=0 thick=0.5 tex=beigewall
slab  x0=21.2 y0=0 z0=0 x1=26.4 y1=0.2 z1=0 thick=0.5 tex=beigewall
