// ===========================================================================
// Light fittings. Every one is a housing hung a little below the surface it
// is on, with the lamp texture on its underside and a point light beneath it.
// ===========================================================================

// The atrium ceiling, in two rows down the length of the room
box   x0=-5.6 y0=9.44 z0=-13.6 x1=-4.8 y1=9.6 z1=-10.4 tex=metal_dark bottom=light_bank light=15 fit
